"""Build the bilingual, page-based Survey for AI portal from the public data projection."""
from pathlib import Path
import json,html,re,hashlib

R=Path(__file__).resolve().parents[1];W=R/'website';O=R/'docs'
def load(p):return json.loads(p.read_text(encoding='utf-8-sig'))
def esc(x):return html.escape(str(x or ''))
def write(p,s):p.parent.mkdir(parents=True,exist_ok=True);p.write_text(s,encoding='utf-8',newline='\n')
def global_data(name):return json.loads((O/'assets/data'/name).read_text(encoding='utf-8').split('=',1)[1].strip().rstrip(';'))

def build():
 C=load(W/'content/portal.json');idx=load(O/'downloads/index.json');L=global_data('library.js')
 asset_tag=hashlib.sha256(b''.join((W/'assets'/p).read_bytes() for p in ['css/portal.css','js/portal.js','js/experience.js','figures/mark.svg'])).hexdigest()[:12]
 pages=C['pages'];langs=['zh','en'];paths={k:('' if k=='home' else k+'/') for k in pages}
 icons={'method':'◇','skill':'⌘','rsi':'◎','data':'↗'}
 def choose(lang,zh,en):return en if lang=='en' else zh
 def route(lang,key):return ('en/' if lang=='en' else '')+paths[key]
 def base(lang,key,body,level=None,title=None,paper_id=None):
  target=route(lang,key) if paper_id is None else ('en/' if lang=='en' else '')+'papers/'+paper_id+'/'
  depth=target.count('/') if level is None else level;prefix='../'*depth or './'
  other='zh' if lang=='en' else 'en';switch=prefix+(route(other,key) if paper_id is None else ('en/' if other=='en' else '')+'papers/'+paper_id+'/')
  info=pages[key];name=info[lang][0]
  archive_css=f'<link rel="stylesheet" href="{prefix}assets/css/app.css">' if paper_id else ''
  data_scripts=(f'<script src="{prefix}assets/data/survey.js"></script><script src="{prefix}assets/data/library.js"></script>') if paper_id is None and key in ['rsi','atlas','cases','compare','reader','explore'] else ''
  order=list(pages);chapter=order.index(key)
  rail_links=''
  for n in order:
   heading=(choose(lang,'通用方法','THE FRAMEWORK') if n=='home' else choose(lang,'RSI 展示实例','RSI WORKED EXAMPLE') if n=='rsi' else '')
   if heading:rail_links+=f'<div class="p-rail-group">{heading}</div>'
   rail_links+=f'<a class="p-chapter-link {"is-current" if key==n else ""}" data-chapter="{n}" href="{prefix}{route(lang,n)}"'+(' aria-current="page"' if key==n else '')+f'><span class="p-chapter-number">{pages[n]["number"]}</span><span>{esc(pages[n][lang][0])}</span><i aria-hidden="true">↗</i></a>'
  def adjacent(n,direction):
   if not 0<=n<len(order):return ''
   k=order[n];return f'<a class="p-adjacent p-{direction}" data-direction="{direction}" href="{prefix}{route(lang,k)}"><span>{choose(lang,"上一节" if direction=="previous" else "下一节","Previous" if direction=="previous" else "Next")} <b>{pages[k]["number"]}</b></span><strong>{esc(pages[k][lang][0])} {"↑" if direction=="previous" else "↓"}</strong></a>'
  rail=f'''<div class="p-rail-backdrop" id="railBackdrop"></div><aside class="p-rail" id="chapterRail" aria-label="{choose(lang,'全部章节','All chapters')}"><div class="p-rail-heading"><span>{choose(lang,'内容导航','CONTENTS')}</span><b>{pages[key]['number']}<em> / 10</em></b></div><nav class="p-chapter-nav" aria-label="{choose(lang,'01–10 完整导航','Chapters 01–10')}">{rail_links}</nav><div class="p-rail-footer"><div class="p-rail-progress"><span></span></div><label class="p-scroll-option"><input id="chapterScroll" type="checkbox" checked><span>{choose(lang,'滚动切换章节','Scroll between chapters')}</span></label><small>{choose(lang,'读至边界，再滚动切换','At a page edge, scroll again to continue')}</small></div></aside>'''
  chapter_end='' if paper_id else f'''<section class="p-chapter-end p-wrap" aria-label="{choose(lang,'继续阅读','Continue reading')}"><div class="p-end-caption"><span>{choose(lang,'继续探索','CONTINUE THE EXPLORATION')}</span><span class="p-end-hint">{choose(lang,'读至底部，再向下滚动进入下一节','At the bottom, scroll again for the next chapter') if chapter<9 else choose(lang,'已到最后一节，可从左侧选择章节','End of the tour. Choose any chapter in the navigation.')}</span></div><div class="p-adjacent-grid">{adjacent(chapter-1,'previous')}{adjacent(chapter+1,'next')}</div></section>'''
  repo='https://github.com/Mr-Tieguigui/survey-for-ai';description=choose(lang,'面向 AI 阅读的领域 Survey 方法与 Skill，RSI 为实例。','A method and Skill for AI-readable research surveys, with RSI as the worked example.')
  return f'''<!doctype html><html lang="{'en' if lang=='en' else 'zh-CN'}"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="{description}"><meta name="theme-color" content="#f5f4ef"><title>{esc(title or name)} · Survey for AI</title><link rel="icon" href="{prefix}assets/figures/mark.svg?v={asset_tag}">{archive_css}<link rel="stylesheet" href="{prefix}assets/css/portal.css?v={asset_tag}"><link rel="alternate" hreflang="en" href="{prefix}{route('en',key)}"><link rel="alternate" hreflang="zh-CN" href="{prefix}{route('zh',key)}"></head><body class="portal-body" data-lang="{lang}" data-view="{key}" data-archive="{str(paper_id is not None).lower()}" data-root="{prefix}"><a class="p-skip" href="#main">{choose(lang,'跳至内容','Skip to content')}</a><div class="p-progress" aria-hidden="true"></div><header class="p-masthead"><a class="p-brand" href="{prefix}{route(lang,'home')}"><img class="p-logo" src="{prefix}assets/figures/mark.svg?v={asset_tag}" width="40" height="40" alt=""><span class="p-wordmark"><b>Survey for AI</b><small>RESEARCH KNOWLEDGE SYSTEM</small></span></a><div class="p-tools"><a id="languageSwitch" class="p-language" href="{switch}" lang="{other}" aria-label="{choose(lang,'Switch to English','切换至中文')}">{choose(lang,'EN','中文')} <span>↔</span></a><button id="themeToggle" aria-label="{choose(lang,'切换明暗主题','Toggle theme')}">◐</button><button id="menuToggle" aria-controls="chapterRail" aria-expanded="false" aria-label="{choose(lang,'打开导航','Open navigation')}">☰</button></div></header>{rail}<div class="p-canvas"><main id="main">{body}</main>{chapter_end}<footer class="p-footer p-wrap"><div><a class="p-brand" href="{prefix}{route(lang,'home')}"><b>Survey for AI</b></a><p>{choose(lang,'方法可适配，依据可追溯。RSI 是当前实例。','Adapt the method. Trace the evidence. RSI is the current example.')}</p></div><div><a href="{repo}">GitHub ↗</a><a href="{repo}/blob/main/README.md">English</a><a href="{repo}/blob/main/README_CN.md">简体中文</a><span>v{C['version']} · {C['updated']}</span></div></footer></div><div class="p-chapter-toast" id="chapterToast" role="status" aria-live="polite"></div>{data_scripts}<script src="{prefix}assets/data/portal.js"></script><script src="{prefix}assets/js/portal.js?v={asset_tag}"></script><script src="{prefix}assets/js/experience.js?v={asset_tag}"></script></body></html>'''
 def hero(lang,key):
  p=pages[key];label,title,desc=p[lang]
  return f'<div class="p-pagehead p-wrap p-reveal"><div class="p-kicker"><span>{p["number"]} / {esc(label)}</span><span>v{C["version"]} · {C["updated"]}</span></div><h1>{esc(title)}</h1><p>{esc(desc)}</p></div>'
 def button(lang,key,label,style=''):
  return f'<a class="p-button {style}" href="{paths[key] if key=="home" else "../"+paths[key]}">{esc(label)} <span>↗</span></a>'
 def content(lang,key):
  t=lambda zh,en:choose(lang,zh,en)
  intro=hero(lang,key)
  if key=='home':
   intro=f'''<section class="p-home p-wrap"><div class="p-home-copy p-reveal"><div class="p-kicker"><span>METHOD · SKILL · KNOWLEDGE</span><span>v{C['version']} / {C['updated']}</span></div><h1>{t('为 AI 时代，<br>重构领域知识。','A field of knowledge.<br>Ready for AI.')}</h1><p class="p-lead">{t('将文献构建成可查询、可追溯、可维护的 Survey。以通用方法与 Skill 为核心，让 AI 从读者问题找到准确的知识入口。','Build queryable, traceable and maintainable surveys. A reusable method and Skill help AI move from a reader question to the right evidence.')}</p><div class="p-actions"><a class="p-button" href="method/">{t('探索构建方法','Explore the method')} ↗</a><a class="p-textlink" href="skill/">{t('使用 Skill','Use the Skill')} →</a></div><div class="p-home-meta">{t('领域可适配 · 版本化证据 · 按需检索','DOMAIN-ADAPTED · VERSIONED EVIDENCE · TARGETED RETRIEVAL')}</div></div><figure class="p-hero-figure p-reveal"><div class="p-figure-meta"><span>FIG. 01 / KNOWLEDGE ARCHITECTURE</span><span>{t('概念模型','CONCEPTUAL MODEL')}</span></div><div id="conceptGraph"></div><figcaption>{t('问题驱动读取，证据约束回答；更新沿依赖传递。','Questions drive retrieval. Evidence bounds answers. Dependencies carry updates.')}</figcaption></figure></section><section class="p-wrap p-home-strip p-reveal"><div><span>01 / METHOD</span><h2>{t('流程是主角。','The workflow comes first.')}</h2><p>{t('适配、取证、关联、综合、回答与维护。每个阶段有自己的输入和验收门槛。','Adapt, curate, relate, synthesize, answer and maintain. Each stage has its own inputs and gates.')}</p></div><div><span>02 / SKILL</span><h2>{t('把方法带到新领域。','Take the method to a new field.')}</h2><p>{t('换掉术语与评价维度，保留身份、版本和引用规则。空工作区始终标为草稿。','Change vocabulary and evaluation dimensions; retain identity, version and citation rules. Empty workspaces stay drafts.')}</p></div><a class="p-example-door" href="rsi/"><span>03 / WORKED EXAMPLE</span><h2>RSI <span>↗</span></h2><p>{t('808 个家族 · 26 分支 · 38 读者模块。进入实例，查看方法怎样落地。','808 families · 26 branches · 38 reader modules. See the method in a real field.')}</p></a></section>'''
  elif key=='method':intro+='''<section class="p-wrap p-step-layout p-reveal"><div id="stageList" class="p-stage-list"></div><div id="stageDetail" class="p-stage-detail" aria-live="polite"></div></section>'''+f'<figure class="p-wrap p-framework-figure p-reveal"><img src="{("../../" if lang=="en" else "../")}assets/figures/framework-overview.svg" alt="{t("构建、组织、检索与增量维护的概念架构图","Conceptual architecture for construction, organization, retrieval and maintenance")}"><figcaption>{t("图 1 · 信息流与证据权限。概念架构不代表已测得的效率提升。","Figure 1 · Information flow and evidence permissions. The architecture does not imply a measured efficiency improvement.")}</figcaption></figure>'
  elif key=='skill':
   intro+=f'''<section class="p-wrap p-skill-layout p-reveal"><div><h2>{t('一份领域契约，一套研究流程。','One domain contract. One research workflow.')}</h2><p>{t('适配器指定纳入排除、检索截止、角色字段、比较轴、关系词汇、读者问题和预算。通用 Skill 管理创建、续跑、证据、关系、综合、问答与增量维护。','The adapter declares inclusion, cutoff, role fields, comparison axes, relation predicates, reader questions and budget. The shared Skill manages creation, resumption, evidence, relations, synthesis, answering and maintenance.')}</p><div class="p-tags"><span>CREATE</span><span>CURATE</span><span>RELATE</span><span>ANSWER</span><span>MAINTAIN</span></div><a class="p-button" href="https://github.com/Mr-Tieguigui/survey-for-ai/blob/main/skill/survey-evidence-ledger/SKILL.md">{t('打开完整 Skill','Read the Skill')} ↗</a><p class="p-note">{t('方法的跨领域有效性仍需受控试验；通用接口不等于已验证所有领域。','Cross-domain effectiveness still needs controlled testing. A portable interface is not validation in every field.')}</p></div><div class="p-code-panel"><div class="p-code-bar"><span>INITIALIZE / DRAFT ONLY</span><button id="copyCode">{t('复制','Copy')}</button></div><pre id="initCode">python skill/survey-evidence-ledger/scripts/init_domain.py \\\n  --output ../my-survey --domain-id my-domain \\\n  --name "My field" --scope "My research question"</pre><div class="p-code-status">{t('✓ 不覆盖旧项目　✓ 不生成虚构论文　✓ 空语料不通过发布验收','✓ Preserves existing work　✓ No invented papers　✓ Empty corpus fails readiness')}</div><h3>{t('AI 的回答契约','The AI answer contract')}</h3><pre>question · corpus_version · answer\nclaim_ids · citations {{url, version, locator}}\ncomparison_conditions · limits · gaps\nstatus: supported | partial | insufficient_evidence</pre></div></section>'''
  elif key=='rsi':intro+=f'''<section class="p-wrap p-reveal"><div id="corpusStats" class="p-stats"></div><div class="p-example-layout"><div><span class="p-eyebrow">RECURSIVE SELF-IMPROVEMENT</span><h2>{t('分别判断闭环、收益与加速。','Separate feedback, gains and acceleration.')}</h2><p>{t('明确改进对象、反馈、保留状态和后继使用。固定模型不单独否认外部反馈，局部结构闭环也不证明通用 RSI 或持续加速。','Identify what changes, feedback, retained state and later use. A fixed model does not by itself negate external feedback; a local structural loop does not prove universal RSI or sustained acceleration.')}</p><p class="p-note">{t('严格原文计划 533/570；37 条来源、版本或定位例外保留。509 张卡保存了正文选段，241 张有评价细节。','Strict primary-review plan: 533/570, with 37 source/version/locator exceptions. 509 dossiers have saved passages and 241 have evaluation details.')}</p></div><div class="p-example-index" id="exampleIndex"></div></div><figure class="p-timeline"><div class="p-figure-meta"><span>REGISTERED WORKS / YEAR</span><span>{t('缺失年份不计入','MISSING YEARS EXCLUDED')}</span></div><div id="yearChart"></div></figure></section>'''
  elif key=='atlas':intro+='''<section class="p-wrap p-reveal"><div class="p-atlas"><div class="p-branch-list" id="branchList"></div><div id="branchPanel" class="p-branch-panel" aria-live="polite"></div></div><figure class="p-network"><div class="p-figure-meta"><span>FIG. 02 / EVIDENCED LINEAGE</span><span>SELECTED SUBGRAPH</span></div><div id="lineageGraph"></div></figure></section>'''
  elif key=='cases':intro+='''<section class="p-wrap p-reveal"><div id="caseTabs" class="p-tabs" role="tablist"></div><div id="casePanel" class="p-case-panel" aria-live="polite"></div></section>'''
  elif key=='compare':intro+=f'''<section class="p-wrap p-reveal"><div id="comparisonTable" class="p-table-scroll"></div><p class="p-note">{t('字段来自已存配置，空缺保留。不同任务、指标、模型和预算不能直接按分数排序。','Fields come from saved configurations; missing values remain explicit. Different tasks, metrics, models and budgets cannot be ranked directly by score.')}</p><a class="p-textlink" href="../reader/">{t('从比较进入问题与答案','Continue to questions and answers')} →</a></section>'''
  elif key=='reader':intro+='''<section class="p-wrap p-reveal"><div id="profileTabs" class="p-tabs"></div><div class="p-reader-layout"><div id="questionList" class="p-question-list"></div><div id="answerPanel" class="p-answer-panel" aria-live="polite"></div></div><div id="moduleRoutes" class="p-module-routes"></div></section>'''
  elif key=='explore':intro+=f'''<section class="p-wrap p-reveal"><div class="p-library-controls"><input id="librarySearch" type="search" aria-label="{t('搜索论文','Search papers')}" placeholder="{t('搜索题名、机制或关键词…','Search titles, mechanisms or keywords…')}"><select id="roleFilter" aria-label="{t('论文角色','Paper role')}"><option value="">{t('全部角色','All roles')}</option></select><select id="branchFilter" aria-label="{t('研究分支','Research branch')}"><option value="">{t('全部分支','All branches')}</option></select></div><div class="p-result-bar"><span id="resultCount" aria-live="polite"></span><label><input type="checkbox" id="onlyPassages">{t('仅已保存正文选段','Saved passages only')}</label></div><div id="libraryRows"></div><button id="loadMore" class="p-button p-load">{t('加载更多','Load more')} ↓</button></section>'''
  elif key=='data':intro+=f'''<section class="p-wrap p-reveal"><div class="p-resource-grid"><a href="https://github.com/Mr-Tieguigui/survey-for-ai"><span>01 / PUBLIC</span><h2>{t('方法与网站仓库','Method & website')}</h2><p>{t('双语介绍、Skill、方法契约、网站源码与公开阅读投影。','Bilingual introduction, Skill, method contracts, website source and public reading views.')}</p><b>GitHub ↗</b></a><a href="https://github.com/Mr-Tieguigui/rsi-survey/raw/refs/heads/main/survey/RSI-Survey-Knowledge.zip"><span>02 / ACCESS REQUIRED</span><h2>{t('完整 RSI 信息包','Complete RSI knowledge')}</h2><p>{t('完整解析与规范账本，需仓库权限；不含网页、GitHub 配置、完整 PDF 或原始缓存。','Full dossiers and canonical ledgers; repository access required. Excludes the website, GitHub configuration, full PDFs and raw caches.')}</p><b>{t('登录后下载','Download when signed in')} ↓</b></a><a href="{'../../' if lang=='en' else '../'}downloads/AI_GUIDE.md"><span>03 / AI RETRIEVAL</span><h2>{t('AI 阅读与引用规则','AI reading & citation rules')}</h2><p>{t('权威层级、最小读取、证据权限和引用边界。','Authority order, minimal retrieval, evidence permissions and citation boundaries.')}</p><b>Markdown ↓</b></a><a href="{'../../' if lang=='en' else '../'}downloads/index.json"><span>04 / PAPER INDEX</span><h2>{t('808 篇机器索引','808-paper machine index')}</h2><p>{t('稳定 ID、角色、分支、解析路径和已存证据定位。','Stable IDs, roles, branches, dossier paths and saved evidence locators.')}</p><b>JSON ↗</b></a></div><div class="p-boundaries"><div><span>RELEASE / v{C['version']}</span><h2>{t('记录进展，也记录例外。','Record progress and exceptions.')}</h2><p>{t('更新：2026-10-23。固定 808 家族、26 分支、38 模块；严格原文计划为 533/570，37 条例外尚存。候选与筛选记录不是额外纳入论文。','Updated 2026-10-23. Fixed scope: 808 families, 26 branches and 38 modules. Strict primary review is 533/570 with 37 remaining exceptions. Candidate and screening rows are not extra admitted papers.')}</p></div><div><span>LANGUAGE / EVIDENCE</span><h2>{t('双语导读，原始档案保真。','Bilingual guidance, faithful archival records.')}</h2><p>{t('主界面、方法、案例与根问题回答提供双语。论文档案保留原始整理语言，英文档案入口对此明确标注。公开页不分发逐字原文选段，也不新增主张准入。','The interface, method, selected cases and root-question answers are bilingual. Dossiers retain their original curatorial language and English entry pages label this. Public views omit verbatim source passages and grant no new claim admissions.')}</p></div></div></section>'''
  return intro
 for lang in langs:
  for key in pages:write(O/route(lang,key)/'index.html',base(lang,key,content(lang,key)))
 # Archive interfaces switch language without silently translating scientific records.
 for x in idx:
  wid=x['work_family_id'];file=O/'papers'/wid/'index.html';text=file.read_text(encoding='utf-8')
  match=re.search(r'<article class="paper-article">(.*?)</article>',text,re.S)
  if not match:raise ValueError('Missing archival article: '+wid)
  body=match.group(1)
  for lang in langs:
   is_en=lang=='en';prefix='../../../' if is_en else '../../';brief=C['case_briefs'].get(wid)
   notice=choose(lang,'档案保留原始整理语言与来源用语。公开页只展示解析及定位，逐字原文选段保存在私有信息包。','This archive retains its original curatorial and source language. Public views contain analysis and locators; verbatim source passages remain in the private package.')
   lead=f'<div class="p-archive-top"><a href="{prefix}{route(lang,"explore")}">← {choose(lang,"文献库","Paper library")}</a><a id="paperMarkdown" href="{prefix}papers/{wid}/paper.md">{choose(lang,"原语言 Markdown","Original-language Markdown")} ↓</a></div><h1 class="p-archive-title">{esc(x["title"])}</h1><div class="p-archive-notice">{notice}</div>'
   if brief:
    b=brief[lang];lead+=f'<section class="p-archive-brief"><span>EDITORIAL BRIEF / {esc(brief["name"])}</span><h2>{esc(b[0])}</h2><p>{esc(b[1])}</p><p><b>{choose(lang,"评价条件","Evaluation conditions")}:</b> {esc(b[2])}</p><p><b>{choose(lang,"结论边界","Limits")}:</b> {esc(b[3])}</p></section>'
   original=f'<article class="paper-article">{body}</article>'
   if is_en:original=f'<details class="p-original"><summary>Open the original curatorial record · Chinese / English</summary>{original}</details>'
   article=f'<div class="p-wrap p-archive">{lead}{original}</div>'
   target=O/('en' if is_en else '')/'papers'/wid/'index.html';write(target,base(lang,'explore',article,title=x['title'],paper_id=wid))
 write(O/'assets/data/portal.js','window.SURVEY_PORTAL='+json.dumps(C,ensure_ascii=True,separators=(',',':'))+';\n')
 for name in ['portal.css']:(O/'assets/css'/name).write_bytes((W/'assets/css'/name).read_bytes())
 for name in ['portal.js','experience.js']:(O/'assets/js'/name).write_bytes((W/'assets/js'/name).read_bytes())
 write(O/'404.html','<!doctype html><meta charset="utf-8"><title>Page not found · Survey for AI</title><h1>404</h1><p><a href="/survey-for-ai/">返回首页 / Return home</a></p>')
 report={'html_pages':len(list(O.rglob('*.html'))),'localized_portal_pages':len(pages)*2,'archive_interfaces':len(idx)*2,'original_language_markdown_files':len(idx),'languages':['zh-CN','en'],'version':C['version'],'scientific_record_translation':'Original records preserved; selected editorial briefs are bilingual.'}
 write(R/'metadata/portal_build.json',json.dumps(report,indent=2)+'\n');print(json.dumps(report))
 return report

if __name__=='__main__':build()
